366	/**
367	 * A pool, as the screen reads it: its members in the order added, the total of their shares (a retired
368	 * member's counting as given) and whether that total is exactly 100.00. Each member of a balanced pool
369	 * has a cut of the sheet's pot: the pot times their share divided by the shares of the members with a cut
370	 * added up, rounded half to even to two decimals (a retired member's, and a member held on the sheet's
371	 * today, 0.00), with the remainder, the pot minus the cuts added up, going to the member with the
372	 * smallest non-zero cut, the latest added on a tie (a member with no cut gets none; when no cut is
373	 * non-zero, to the last member with a cut and a share), so the cuts total exactly the pot (each is 0.00
374	 * when no member has a cut). A pool whose every member is retired has no cuts. A hold or a retirement changes neither the total nor whether the pool is balanced. An
375	 * unbalanced pool, or no pot, has no cuts. A member whose dates do not include the sheet's today is
376	 * left out entirely: not in the total, not in the balance, and no cut (not even 0.00). A pool that is a member of another has no pot of its own: its
377	 * pot is its cut in the pool above (none when that pool has no cuts). {@code added} orders the pools as they
378	 * were added (a larger one added later).
379	 */
380	public record PoolResponse(String name, List<PoolMemberResponse> members, String totalShare, boolean balanced,
381	        long added) {
382	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
383	
384	    public static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot) {
385	        BigDecimal total = total(members);
386	        boolean balanced = total.compareTo(HUNDRED) == 0;
387	        List<BigDecimal> cuts = cutsOf(members, pot);
388	        List<PoolMemberResponse> shown = new ArrayList<>();
389	        for (int i = 0; i < members.size(); i++) {
390	            shown.add(PoolMemberResponse.from(members.get(i), cuts == null ? null : cuts.get(i)));
391	        }
392	        return new PoolResponse(pool.name(), shown, total.toPlainString(), balanced, pool.id());
393	    }
394	
395	    /** The active members' shares added up, a retired member's counting as given. */
396	    static BigDecimal total(List<PoolMember> members) {
397	        BigDecimal total = BigDecimal.ZERO.setScale(2);
398	        for (PoolMember m : members) if (m.active()) total = total.add(m.share());
399	        return total;
400	    }
401	
402	    /**
403	     * Each member's cut of the pot, in the members' order; null when the pool is unbalanced, there is no pot,
404	     * or every member is retired.
405	     */
406	    static List<BigDecimal> cutsOf(List<PoolMember> members, BigDecimal pot) {
407	        boolean allRetired = members.stream().filter(PoolMember::active).allMatch(PoolMember::retired);
408	        return pot != null && !allRetired && total(members).compareTo(HUNDRED) == 0 ? cuts(members, pot) : null;
409	    }
410	
411	    /** Whether the member has a cut: active, neither retired nor held on the sheet's today. */
412	    private static boolean hasCut(PoolMember m) {
413	        return m.active() && !m.retired() && !m.held();
414	    }
415	
416	    private static List<BigDecimal> cuts(List<PoolMember> members, BigDecimal pot) {
417	        BigDecimal shares = BigDecimal.ZERO;
418	        for (PoolMember m : members) if (hasCut(m)) shares = shares.add(m.share());
419	        List<BigDecimal> cuts = new ArrayList<>();
420	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
421	        int smallest = -1;
422	        int lastShared = -1;
423	        for (int i = 0; i < members.size(); i++) {
424	            PoolMember m = members.get(i);
425	            if (!m.active()) {
426	                cuts.add(null);
427	                continue;
428	            }
429	            BigDecimal cut = !hasCut(m) || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
430	                    : pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN);
431	            cuts.add(cut);
432	            sum = sum.add(cut);
433	            if (!hasCut(m)) continue;
434	            if (m.share().signum() > 0) lastShared = i;
435	            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) smallest = i;
436	        }
437	        int to = smallest >= 0 ? smallest : lastShared;
438	        if (to >= 0 && shares.signum() > 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
439	        return cuts;
440	    }
