631	    public void validate(@RequestBody PoolMemberRequest request, Out<PoolMemberInput> body) throws InvalidPoolException {
632	        if (request == null) throw new InvalidPoolException("A pool member is required");
633	        String pool = request.pool() == null ? "" : request.pool().trim();
634	        if (pool.isEmpty()) throw new InvalidPoolException("A pool is required");
635	        String memberPool = request.memberPool() == null ? "" : request.memberPool().trim();
636	        Long personId = null;
