641	                throw new InvalidPoolException("A person or a pool is required");
642	            }
643	        }
644	        String text = request.share() == null ? "" : request.share().trim();
645	        if (!text.matches("\\d+(\\.\\d{1,2})?")) throw new InvalidPoolException("A share is a number with at most two decimals");
646	        BigDecimal share = new BigDecimal(text).setScale(2);
647	        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
648	            throw new InvalidPoolException("A share is more than 0.00 and at most 100.00");
649	        }
650	        LocalDate from = date(request.from(), "A from-date is a date");
